-- ============================================================
-- MIGRATION: 0009_course_certificate_history.sql
-- TARGET DATABASE: Supabase PostgreSQL (public schema)
-- PURPOSE: Provision Course Completion Certificate history table
-- CONVENTIONS & SAFETY:
--   - Idempotent table and index creation (IF NOT EXISTS)
--   - Uses GENERATED BY DEFAULT AS IDENTITY for primary key
--   - Relies on UNIQUE constraint index for certificate_id lookup
--   - Row Level Security (RLS) enabled
--   - Strict permissions: revokes anon/authenticated, grants to service_role
-- ============================================================

-- 1. Table structure
CREATE TABLE IF NOT EXISTS public.course_certificate_history (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    certificate_id TEXT NOT NULL UNIQUE,
    student_name TEXT NOT NULL,
    student_email TEXT NOT NULL,
    course_name TEXT NOT NULL,
    issued_date TEXT NOT NULL,
    generated_date TIMESTAMPTZ DEFAULT timezone('utc'::text, now()),
    created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()),
    certificate_status TEXT DEFAULT 'active',
    email_status TEXT DEFAULT 'pending',
    sent_at TIMESTAMPTZ,
    send_count INT DEFAULT 0,
    pdf_filename TEXT,
    error_message TEXT,
    template_version TEXT DEFAULT 'v1'
);

-- 2. Query & performance indexes
-- Note: A separate index on certificate_id is omitted because the UNIQUE constraint
-- automatically creates a unique B-tree index in PostgreSQL.
CREATE INDEX IF NOT EXISTS idx_course_cert_created_at 
    ON public.course_certificate_history (created_at DESC);

CREATE INDEX IF NOT EXISTS idx_course_cert_sent_at 
    ON public.course_certificate_history (sent_at DESC);

CREATE INDEX IF NOT EXISTS idx_course_cert_student_email 
    ON public.course_certificate_history (student_email);

CREATE INDEX IF NOT EXISTS idx_course_cert_email_status 
    ON public.course_certificate_history (email_status);

-- 3. Row Level Security & Access Control
ALTER TABLE public.course_certificate_history ENABLE ROW LEVEL SECURITY;

-- Revoke public, anonymous, and standard authenticated access
REVOKE ALL ON TABLE public.course_certificate_history FROM anon, authenticated;

-- Grant required operations exclusively to the backend service_role
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.course_certificate_history TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public.course_certificate_history_id_seq TO service_role;
